// ─── CONFIGURE ────────────────────────────────────────────────────────────
const BUSINESS_TYPE = 'dentist';   // what to search for: 'plumber', 'accountant', 'vet', 'estate agent' …

// Areas to sweep. Sweeping postcode districts gives far fuller coverage than one
// big city query, because Google Places caps how many results a single search returns.
const AREAS = [
  'M1 Manchester UK',
  'M2 Manchester UK',
  'M3 Manchester UK',
  'M4 Manchester UK',
];

// Only keep results whose name contains one of these words (lowercase).
// Leave empty [] to keep everything the search returns.
const NAME_KEYWORDS = [];          // e.g. ['dental', 'dentist']

// Skip results whose name contains any of these (lowercase) — use it to
// exclude national chains and franchises so you only capture independents.
const EXCLUDE_NAMES = [];          // e.g. ['bupa', 'mydentist']

// Contact emails are only accepted on the business's own domain. Add extra
// trusted domains here if your niche uses shared ones (e.g. 'nhs.net' for UK healthcare).
const EXTRA_EMAIL_DOMAINS = [];

const DEFAULT_MAX = 12;            // manual runs: how many leads to capture per run (the CRM trigger sends its own)
// ─── END CONFIGURE ────────────────────────────────────────────────────────

const sd = $getWorkflowStaticData('global');
sd.allPlaces = [];
sd.seenKeys = {};
sd.crmLeads = [];                  // accumulator for the optional CRM sync
sd.config = { NAME_KEYWORDS, EXCLUDE_NAMES, EXTRA_EMAIL_DOMAINS };

function uuid(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){const r=Math.random()*16|0,v=c==='x'?r:(r&0x3|0x8);return v.toString(16);});}

// If a CRM started this run through the webhook, reuse its run_id and maxLeads.
let runId, maxLeads;
try { const b = $('CRM webhook trigger (optional)').first().json.body || {}; runId = b.run_id; maxLeads = parseInt(b.maxLeads, 10); } catch (e) {}
sd.runId = runId || uuid();
sd.maxLeads = (maxLeads && maxLeads > 0) ? maxLeads : DEFAULT_MAX;

return AREAS.map(a => ({ json: { area: BUSINESS_TYPE + ' ' + a } }));

const resp = $input.first().json || {};
const places = resp.places || [];
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.allPlaces)) sd.allPlaces = [];
if (!sd.seenKeys) sd.seenKeys = {};

const cfg = sd.config || {};
const keywords = (cfg.NAME_KEYWORDS || []).map((s) => String(s).toLowerCase());
const excluded = (cfg.EXCLUDE_NAMES || []).map((s) => String(s).toLowerCase());

function getDomain(u){ return !u ? '' : u.replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].split('?')[0]; }

for (const pl of places) {
  const title = (pl.title || '').toLowerCase();
  // Keyword filter (only if configured) — keeps the list on-topic.
  if (keywords.length && !keywords.some((k) => title.includes(k))) continue;
  // Exclusion filter — skip chains and franchises.
  if (excluded.some((c) => title.includes(c))) continue;
  // Dedupe within this run (the same place appears in overlapping area searches).
  const key = pl.cid || (title + '|' + (pl.address || '').toLowerCase());
  if (sd.seenKeys[key]) continue;
  sd.seenKeys[key] = true;
  sd.allPlaces.push({
    name: pl.title || '', address: pl.address || '', phone: pl.phoneNumber || '',
    website: pl.website || '', domain: getDomain(pl.website || ''), cid: pl.cid || ''
  });
}
return [{ json: { collected: sd.allPlaces.length } }];

// Cap to the requested number of leads (webhook maxLeads, else DEFAULT_MAX from CONFIGURE).
const sd = $getWorkflowStaticData('global');
const all = sd.allPlaces || [];
const max = sd.maxLeads || 0;
const list = max > 0 ? all.slice(0, max) : all;
return list.map(p => ({ json: p }));

const existing = $input.all().map(i => String(i.json['Place ID'] || '').trim()).filter(Boolean);
const seen = new Set(existing);
return $('Finalize lead list').all().filter(p => !p.json.cid || !seen.has(String(p.json.cid).trim()));

const p = $('Loop over businesses').first().json;
const sd = $getWorkflowStaticData('global');
sd.currentBusiness = p;
return [{ json: { ...p } }];

const sd = $getWorkflowStaticData('global');
const p = sd.currentBusiness || {};
const domain = (p.domain || '').toLowerCase();
const extraDomains = ((sd.config && sd.config.EXTRA_EMAIL_DOMAINS) || []).map((x) => String(x).toLowerCase());

function clean(raw){ return String(raw||'').slice(0,200000).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' '); }
function ok(e){
  e = e.toLowerCase();
  if (/\.(png|jpe?g|gif|webp|svg|css|js)$/.test(e)) return false;   // regex matches inside asset filenames
  if (domain && e.endsWith('@' + domain)) return true;              // the business's own domain
  if (extraDomains.some((x) => e.endsWith('@' + x))) return true;   // extra trusted domains from CONFIGURE
  return false;
}
function findEmail(html){
  const mailto = html.match(/mailto:([\w.+-]+@[\w-]+(?:\.[\w-]+)+)/i);
  if (mailto && ok(mailto[1])) return mailto[1];
  const found = html.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g) || [];
  for (const m of found){ if (ok(m)) return m; }
  return '';
}
const home = clean($('Fetch website homepage').first().json.data || $('Fetch website homepage').first().json.body || '');
let contactHtml = '';
try { contactHtml = clean($('Fetch contact page').first().json.data || $('Fetch contact page').first().json.body || ''); } catch(e){}
const email = findEmail(home) || findEmail(contactHtml);
p.email = email; sd.currentBusiness = p;
return [{ json: { ...p, email } }];

const sd = $getWorkflowStaticData('global');
const p = sd.currentBusiness || {};
let email = p.email || '';
let firstName = '', lastName = '', position = '';
try {
  const h = $('Hunter.io email lookup').first().json || {};
  const emails = ((h.data && h.data.emails) || []).sort((a,b)=>(b.confidence||0)-(a.confidence||0));
  if (emails.length) {
    if (!email) email = emails[0].value || '';
    const best = emails.find(e => (e.value||'').toLowerCase() === email.toLowerCase()) || emails[0];
    firstName = best.first_name || ''; lastName = best.last_name || ''; position = best.position || '';
  }
} catch(e){}
const contactName = [firstName, lastName].filter(Boolean).join(' ');
let phone = p.phone || '';
if (phone && /^[+=]/.test(String(phone))) phone = "'" + phone;   // sheet-safe
let score = 0;
if (email) score += 45;
if (p.phone) score += 25;
if (p.website) score += 20;
if (contactName) score += 10;
const tier = score >= 75 ? 'Hot' : score >= 50 ? 'Warm' : score >= 25 ? 'Cold' : 'Not a Fit';
return [{ json: {
  'Company': p.name || '',
  'Email': email,
  'Phone': phone,
  'Website': p.website || '',
  'Address': p.address || '',
  'Place ID': p.cid || '',
  'Captured On': new Date().toISOString().slice(0,10),
  contact_name: contactName, contact_position: position, ai_score: score, ai_tier: tier
}}];

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.crmLeads)) sd.crmLeads = [];
const r = $json;
const email = String(r['Email'] || '').trim();
let phone = String(r['Phone'] || '').replace(/^'/, '').trim();
// QUALITY GATE: never push a lead to the CRM without an email or phone.
if (email || phone) {
  const lead = {
    company_name: String(r['Company'] || '').trim(),
    contact_name: (String(r['contact_name'] || '').trim()) || null,
    contact_position: (String(r['contact_position'] || '').trim()) || null,
    contact_email: email || null,
    contact_phone: phone || null,
    website: (String(r['Website'] || '').trim()) || null,
    location: (String(r['Address'] || '').trim().slice(0, 120)) || null,
    ai_score: typeof r['ai_score'] === 'number' ? r['ai_score'] : null,
    ai_tier: ['Hot','Warm','Cold','Not a Fit'].includes(r['ai_tier']) ? r['ai_tier'] : null,
    source: 'n8n-lead-capture'
  };
  if (lead.company_name) sd.crmLeads.push(lead);
}
return [{ json: r }];

// Runs ONCE when the business loop is finished (the SplitInBatches 'done' branch).
// Builds the exact JSON body the CRM webhook will receive and HMAC-verify.
const sd = $getWorkflowStaticData('global');
const leads = Array.isArray(sd.crmLeads) ? sd.crmLeads : [];
if (leads.length === 0) return [];  // nothing captured -> skip the CRM call
const runId = sd.runId || '+1234567890+1234567890';
// IMPORTANT: this exact string is what gets signed AND sent, byte-for-byte.
const payload = JSON.stringify({ run_id: runId, status: 'completed', leads });
return [{ json: { payload, count: leads.length, runId } }];

const sd = $getWorkflowStaticData('global');
const p = sd.currentBusiness || {};
const base = p.website || '';
const html = String($('Fetch website homepage').first().json.data || $('Fetch website homepage').first().json.body || '');
let url = '';
const m = html.match(/href=["']([^"']*contact[^"']*)["']/i);
if (m) { const href = m[1]; if (/^https?:\/\//i.test(href)) url = href; else if (base) { try { url = new URL(href, base).href; } catch(e){} } }
if (!url && p.domain) url = 'https://' + p.domain + '/contact';
return [{ json: { ...p, contactUrl: url || 'https://httpbin.org/html' } }];
